CREATE POLICY feedback_admin_read ON public.feedback FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin')); CREATE FUNCTION public.restrict_staff_menu_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.has_role(auth.uid(),'staff') AND NOT public.has_role(auth.uid(),'admin') THEN IF (to_jsonb(NEW)-'is_available'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'is_available'-'updated_at') THEN RAISE EXCEPTION 'Staff may only change availability'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER staff_menu_update BEFORE UPDATE ON public.menu_items FOR EACH ROW EXECUTE FUNCTION public.restrict_staff_menu_update();